def lastDayToCross(row, col, cells):
    total = row * col
    top, bottom = total, total + 1
    parent = list(range(total + 2))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb

    land = [False] * total
    for i in range(total - 1, -1, -1):
        r, c = cells[i][0] - 1, cells[i][1] - 1
        idx = r * col + c
        land[idx] = True
        if r == 0:
            union(idx, top)
        if r == row - 1:
            union(idx, bottom)
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < row and 0 <= nc < col and land[nr * col + nc]:
                union(idx, nr * col + nc)
        if find(top) == find(bottom):
            return i
    return 0
